def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Count history stats directly (avoid building lists too often)
    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
        if me == 'C':
            my_c += 1
        if me == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    my_d = n - my_c

    # Recent window stats
    w = 12
    if n < w:
        start = 0
    else:
        start = n - w
    rc = 0
    rd = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            rc += 1
        else:
            rd += 1
    rlen = n - start

    # Opponent's defection streak
    run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_d += 1
        else:
            break

    # Opponent's cooperation streak
    run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_c += 1
        else:
            break

    # If opponent has never defected, mostly cooperate with rare late exploit.
    if opp_d == 0:
        if n >= 95:
            # Late-game exploitation window
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # If opponent almost never cooperates, defect.
    if opp_c == 0:
        return 'D'
    if n >= 6 and opp_c <= 1 and opp_d >= 3:
        return 'D'

    # Punish sustained defection
    if run_d >= 3:
        return 'D'

    # Two-in-a-row defection from opp: retaliate, but forgive if overall cooperative.
    if opp_last == 'D':
        # If opponent has been highly cooperative overall, forgive sometimes.
        if opp_d <= 2 and n >= 8:
            return 'C'
        if opp_d * 3 <= n:
            # Mostly cooperative opponent: retaliate once, then likely recover.
            return 'D'
        # Mixed/bad opponent: defect
        return 'D'

    # Opponent cooperated last round.
    # If we defected last and opp still cooperates, they're forgiving: exploit sometimes.
    if my_last == 'D':
        if opp_c * 2 >= n and n >= 8:
            # Opponent is fairly cooperative; punish us rarely. Exploit with moderate freq.
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated last round (usual state).
    # If opponent heavily coops, cooperate mostly, rare strategic defection.
    if opp_c * 4 >= n * 3 and n >= 10:
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # If opponent's recent cooperation is high, cooperate.
    if rlen > 0 and rc * 4 >= rlen * 3:
        return 'C'

    # Mixed opponents: cooperate to encourage reciprocity, defect if they've been bad lately.
    if rlen > 0 and rd * 2 >= rlen:
        # Recent opponent behavior is bad; defect more often.
        return 'D' if rng.random() < 0.7 else 'C'

    return 'C'
